func TestConcurrentUse(t *testing.T) {
	clock := newFakeClock(time.Unix(0, 0))
	l, err := NewLimiter(100, 10, clock)
	if err != nil {
		t.Fatalf("NewLimiter: %v", err)
	}
	var (
		wg       sync.WaitGroup
		allowed  int64
		mu       sync.Mutex
	)
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.Allow() {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed != 10 {
		t.Errorf("allowed = %d, want 10 (burst)", allowed)
	}
}
